DROP TABLE IF EXISTS `baseline_revisions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `baseline_revisions` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_version` int(11) NOT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `impact` text COLLATE utf8mb4_unicode_ci,
  `previous_target_date` date DEFAULT NULL,
  `proposed_target_date` date DEFAULT NULL,
  `plan_snapshot` json NOT NULL,
  `status` enum('pending','approved','rejected','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `requested_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requested_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `decided_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decided_at` datetime(3) DEFAULT NULL,
  `decision_comment` text COLLATE utf8mb4_unicode_ci,
  `baseline_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pending_key` char(36) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (if((`status` = 'pending'),`project_id`,NULL)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `baseline_revisions_one_pending` (`pending_key`),
  KEY `baseline_revisions_project_idx` (`project_id`),
  KEY `baseline_revisions_reqby_fk` (`requested_by`),
  KEY `baseline_revisions_decby_fk` (`decided_by`),
  KEY `baseline_revisions_baseline_fk` (`baseline_id`),
  CONSTRAINT `baseline_revisions_baseline_fk` FOREIGN KEY (`baseline_id`) REFERENCES `project_baselines` (`id`),
  CONSTRAINT `baseline_revisions_decby_fk` FOREIGN KEY (`decided_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `baseline_revisions_project_fk` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`),
  CONSTRAINT `baseline_revisions_reqby_fk` FOREIGN KEY (`requested_by`) REFERENCES `profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

