INSERT INTO `insight_rules` VALUES ('activity_overdue','Activity overdue','Activity past plan finish and not completed','warning',NULL,NULL,0,1),('critical_bug_open','Critical bug open','Critical bug not closed','critical',NULL,NULL,1,1),('delay_no_recovery','Delay without Recovery Plan','Delayed / overdue activity without a recovery plan','critical',NULL,NULL,0,1),('evidence_missing','Mandatory evidence missing','Mandatory checklist items missing for finished / due items','warning',NULL,NULL,0,1),('fix_overdue','Bug fix overdue','Bug fix past due date','warning',NULL,NULL,1,1),('forecast_vs_baseline','Forecast exceeds Baseline','Forecast finish later than baseline by more than X days','warning',0,'days',0,1),('member_overloaded','Member overloaded','Person with more than X open tasks + bugs','info',8,'open items',1,1),('no_baseline','No baseline','Project still without Baseline V1 after X days','warning',14,'days',0,1),('no_leader','No Project Leader','Project has no leader','critical',NULL,NULL,0,1),('no_next_action','No Next Action','Project or in-progress activity without next action','info',NULL,NULL,0,1),('no_target_date','No Required / Target Date','Active project without target date','warning',NULL,NULL,0,1),('owner_on_leave','Owner on leave on due date','Task owner / PIC planned leave on the due date (next X days)','warning',14,'days ahead',1,1),('progress_stale','Progress not updated','In-progress activity not updated for more than X days','info',7,'days',0,1),('recovery_not_reviewed','Recovery plan not reviewed','Recovery plan not reviewed by Supervisor/Manager within X days','info',3,'days',0,1),('retest_overdue','Retest overdue','Retest past due date','warning',NULL,NULL,1,1),('too_many_reschedules','Rescheduled too many times','Baseline revised more than X times','warning',2,'revisions',0,1),('waiting_too_long','Waiting too long','Activity / project in Waiting or On Hold longer than X days','warning',7,'days',0,1);
