DROP TABLE IF EXISTS `internal_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `internal_tasks` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_no` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `activity_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parent_task_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seq` int(11) NOT NULL DEFAULT '0',
  `name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_type` enum('design','dev','qa','review','doc','deploy','support','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'dev',
  `owner_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reviewer_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `planned_start` date DEFAULT NULL,
  `due_date` date NOT NULL,
  `actual_start` date DEFAULT NULL,
  `actual_finish` date DEFAULT NULL,
  `progress` decimal(5,2) NOT NULL DEFAULT '0.00',
  `status` enum('todo','in_progress','waiting','review','completed','on_hold','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'todo',
  `description` text COLLATE utf8mb4_unicode_ci,
  `technical_note` text COLLATE utf8mb4_unicode_ci,
  `internal_comment` text COLLATE utf8mb4_unicode_ci,
  `delay_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delay_reason` text COLLATE utf8mb4_unicode_ci,
  `recovery_action` text COLLATE utf8mb4_unicode_ci,
  `created_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `internal_tasks_no_uq` (`project_id`,`task_no`),
  KEY `internal_tasks_activity_idx` (`activity_id`,`seq`),
  KEY `internal_tasks_owner_idx` (`owner_id`,`status`),
  KEY `internal_tasks_parent_idx` (`parent_task_id`),
  KEY `internal_tasks_reviewer_fk` (`reviewer_id`),
  KEY `internal_tasks_createdby_fk` (`created_by`),
  CONSTRAINT `internal_tasks_activity_fk` FOREIGN KEY (`activity_id`) REFERENCES `activities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `internal_tasks_createdby_fk` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `internal_tasks_owner_fk` FOREIGN KEY (`owner_id`) REFERENCES `profiles` (`id`),
  CONSTRAINT `internal_tasks_parent_fk` FOREIGN KEY (`parent_task_id`) REFERENCES `internal_tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `internal_tasks_project_fk` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `internal_tasks_reviewer_fk` FOREIGN KEY (`reviewer_id`) REFERENCES `profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
